@sig trait Mining_Eligibility_Api {
  def id: Art.BridgeId
  def intent_Id : Art.PortId
  def threat_disposition_Id : Art.PortId
  def assessment_Id : Art.PortId
  def recovery_gate_Id : Art.PortId
  def mining_proposal_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var mining_proposal: Mining_Threat_Retreat_Supervision.ProposalValue = $

  def put_mining_proposal(value : Mining_Threat_Retreat_Supervision.ProposalValue) : Unit = {
    Contract(
      Modifies(mining_proposal),
      Ensures(
        mining_proposal == value
      )
    )
    Spec {
      mining_proposal = value
    }

    Art.putValue(mining_proposal_Id, Mining_Threat_Retreat_Supervision.ProposalValue_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

